"""Explain unmap ordering, successful copy lengths and metadata-only hooks."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1813': ('한 칸의 물건을 찾은 뒤 남은 칸 전체의 안내표를 지우면, 다음 칸에서는 물건을 찾을 길이 없어질 수 있어요. 작업 순서가 다음 조회에 영향을 줘요.', '현재 페이지 조회와 남은 전체 범위 연결 해제의 순서를 이해합니다.', '두 페이지 A·B의 연결표를 그리고 A 조회 → A와 B 연결 제거 → B 조회 순서를 따라가세요.', ['kmsan_iounmap_page_range는 검사 페이지의 가상 연결을 정리하는 함수예요. 먼저 활성 상태와 runtime 조건을 확인해요. 정상 경로에서는 페이지 수를 계산하고 도구 처리에 들어가 shadow와 origin 시작 주소를 구해요.', '각 반복은 현재 shadow 주소와 origin 주소로 페이지를 먼저 조회해요. 그 결과를 지역 포인터 shadow와 origin에 보관해요. 조회가 먼저이므로 바로 뒤 연결을 없애더라도 이미 얻은 포인터는 지역 변수에 남아 있어요.', '그다음 unmap의 시작에는 현재 주소를, 끝에는 전체 범위의 end에 대응하는 주소를 넣어요. 현재 주소에 PAGE_SIZE를 더한 한 페이지 끝이 아니에요. 첫 반복에서는 뒤쪽 페이지들의 연결까지 함께 제거할 수 있어요.', '연결을 제거한 뒤 앞서 얻은 포인터가 NULL이 아니면 __free_pages로 반납해요. 이어 반복 갱신식이 현재 주소를 한 페이지씩 늘려요. 다음 반복은 새 주소로 다시 페이지를 조회하므로 앞에서 지운 연결의 영향을 받아요.', '두 페이지 연결표 모델에서는 첫 반복이 A의 검사 페이지들을 조회한 뒤 A와 B의 연결을 지워요. 다음 B 조회는 연결표에 항목이 없어 NULL이 될 수 있어요. 따라서 반복문이 두 번 돈다는 사실만으로 두 페이지의 모든 자원이 반납된다고 증명할 수 없어요.', '끝에서는 두 범위의 캐시 처리와 runtime 종료를 요청해요. 이 수업은 고정 코드의 순서와 제한된 연결표 모델을 설명해요. 실제 커널 할당자에서 누수를 재현했거나 모든 호출 경로의 수명을 검증한 것은 아니에요.'], [('반복 안의 unmap이 사용하는 끝 주소는 무엇인가요?', ['항상 현재 주소에서 한 페이지 뒤예요', '전체 범위 end에 대응하는 검사 정보 주소예요'], '정답은 두 번째예요. vmalloc_shadow(end)와 vmalloc_origin(end)가 쓰여요. 반복문이라는 이유만으로 한 페이지만 지운다고 추측하면 안 돼요.'), ('현재 검사 페이지의 포인터는 연결을 없애기 전과 후 중 언제 얻나요?', ['연결을 없애기 전에 조회해요', '연결을 없앤 다음에 처음 조회해요'], '정답은 첫 번째예요. 조회 두 번 → 연결 해제 두 번 → 조건부 free 순서예요. 다음 반복은 다시 조회하므로 앞선 연결 제거의 영향을 따로 생각해야 해요.')]), 'os1814': ('여덟 장을 보내려 했는데 세 장이 남았다면 실제 보낸 것은 다섯 장이에요. 요청한 양과 끝난 양을 구분해 검사해요.', '요청 길이와 미복사 잔여로 실제 처리 길이를 계산합니다.', '요청 8에서 잔여 0·3·8을 각각 빼 보고, 잔여 9는 계산 전에 돌아가는 조건에 표시하세요.', ['kmsan_copy_to_user는 사용자 공간으로 복사를 시도한 뒤 부르는 검사 hook예요. 사용자 공간은 일반 프로그램이 사용하는 영역이에요. 실제 복사 자체를 이 함수가 새로 실행하는 것은 아니에요.', '주석은 이 시점에 이미 복사했고 그 뒤에야 실제 복사량을 알 수 있다고 설명해요. to_copy는 요청량, left는 아직 복사하지 못한 잔여량이에요. 정상 복사 API에서는 잔여량이 요청량보다 클 수 없다는 조건을 함께 기억하세요.', '검사가 꺼졌거나 runtime 안이면 먼저 돌아가요. 다음으로 요청량이 0이면 돌아가고 to_copy <= left인 경우에도 돌아가요. 조건은 같거나 크다는 경우를 모두 포함해요.', '요청 8, 잔여 3이면 처리 길이는 8 - 3 = 5바이트예요. 요청 8, 잔여 0이면 8바이트예요. 실제로 성공한 부분의 검사나 검사 정보 이동에 이 길이를 전달해요.', '요청 8, 잔여 8이면 복사한 양이 없으므로 돌아가요. 잔여 9라는 비정상 입력도 이 함수의 조건에서는 뺄셈 전에 돌아가요. 음수가 없는 size_t에서 8 - 9를 계산해 큰 숫자가 되는 경로를 여기서 실행하지 않아요.', '이 설명은 복사 뒤의 hook가 계산하는 범위예요. 복사 전 wrapper가 요청 전체를 검사하는지와는 별도 문제예요. 모델에서는 실제 사용자 메모리에 쓰지 않고 숫자와 전달 길이를 계산할 수 있어요.'], [('요청량이 8바이트이고 잔여량이 3바이트라면 이 hook의 처리 길이는 얼마인가요?', ['항상 요청 전체인 8바이트예요', '실제로 복사한 5바이트예요'], '정답은 두 번째예요. 8 - 3 = 5예요. left는 복사한 양이 아니라 아직 남은 양이에요.'), ('잔여량이 요청량보다 큰 경우 이 함수는 먼저 뺄셈하나요?', ['아니요. to_copy <= left 조건에서 돌아가요', '네. 먼저 뺀 큰 값을 그대로 처리해요'], '정답은 첫 번째예요. 뺄셈 식은 조기 반환 조건 뒤에 있어요. 비정상 잔여가 정상 API 사용이라는 뜻은 아니지만 이 함수의 분기는 그렇게 읽어야 해요.')]), 'os1815': ('보내는 곳이 건물 밖인지 같은 건물 안인지에 따라 확인할 일이 달라요. 목적지 주소를 분류한 뒤 검사 또는 검사표 이동을 선택해요.', '주소 분류에 따른 사용자 검사와 커널 내부 검사 정보 이동을 구별합니다.', '분리 설정 꺼짐·켜짐 두 줄과 낮은 주소·높은 주소 두 칸으로 네 경우를 표시하세요.', ['이 수업은 요청량에서 잔여량을 뺀 성공 길이가 있는 경로예요. 먼저 user_access_save의 결과를 ua_flags에 보관해요. 사용자 메모리 접근 관련 상태를 뒤에서 원래대로 복구하는 데 쓰는 값이에요.', '조건은 주소 공간 분리 설정이 꺼져 있거나 목적지 to가 TASK_SIZE보다 작은지예요. 둘 중 하나라도 참이면 사용자 공간 접근으로 처리해요. TASK_SIZE는 이 비교에서 사용자 주소 범위의 경계예요.', '사용자 경로는 원본 from의 성공한 범위를 kmsan_internal_check_memory에 전달해요. 이유 표시는 REASON_COPY_TO_USER예요. 준비되지 않은 내용이 외부로 전달되는 문제를 검사하며, 항상 오류 보고가 나온다는 뜻은 아니에요.', '설정이 켜져 있고 to가 경계 이상이면 else로 가요. 여기서는 검사 정보 이동 도우미에 to, from, 성공 길이를 전달해요. 실제 데이터는 이미 복사된 뒤이므로 또 복사하는 코드가 아니에요.', '주석은 호환용 시스템 호출이 커널 스택에 준비한 인자를 다른 시스템 호출로 넘기는 경우를 설명해요. 호환용 호출은 다른 프로그램 실행 형식과 맞추는 경로예요. 이름이 copy_to_user여도 이 조건에서는 커널 내부 목적지로 다뤄요.', '두 분기가 정상적으로 끝나면 공통으로 user_access_restore(ua_flags)를 호출해요. 무조건 새 숫자 0을 넣는 것이 아니라 앞에서 받은 상태값을 사용해요. 검사 종류 선택과 접근 상태 복구는 별개 작업이에요.'], [('주소 공간 분리 설정이 켜졌고 목적지가 커널 범위라면 어떤 처리를 하나요?', ['항상 사용자 유출 오류를 보고해요', '성공한 길이만큼 검사 정보를 이동해요'], '정답은 두 번째예요. 그 조건은 else로 이어져 metadata 이동을 호출해요. 실제 데이터 복사는 이미 끝난 시점이에요.'), ('두 분기 뒤 복구하는 ua_flags는 어디서 얻었나요?', ['앞의 user_access_save 반환값이에요', '언제나 새로 만든 상수 0이에요'], '정답은 첫 번째예요. 지역 변수에 저장했던 원래 상태를 restore에 넘겨요. 분기가 달라도 정상 종료 시 복구하는 흐름은 공통이에요.')]), 'os1816': ('이삿짐을 옮기는 담당자와 짐의 검사표를 옮기는 담당자가 따로 있어요. 비슷한 함수 이름이라도 어느 일을 맡는지 본문으로 확인해요.', 'kmsan_memmove와 __msan_memmove의 데이터·검사 정보 책임을 구별합니다.', '실제 데이터 이동과 검사 정보 이동 두 줄을 그린 뒤 kmsan_memmove는 검사 정보 줄에 놓으세요.', ['kmsan_memmove는 메모리 이동에 맞춰 검사 정보를 옮기는 hook예요. to는 도착 주소, from은 원본 주소, size는 바이트 수예요. 이름에 memmove가 있지만 실제 데이터 이동 함수를 직접 호출하지 않아요.', '먼저 KMSAN이 꺼졌거나 도구 자신의 처리 중이면 돌아가요. 정상 경로는 enter_runtime → kmsan_internal_memmove_metadata → leave_runtime 순서예요. 내부 helper를 실행할 때는 runtime에 들어간 상태예요.', 'metadata는 shadow 준비 상태표와 origin 원인 정보 같은 검사 정보를 뜻해요. 데이터를 옮긴 뒤 그 내용이 준비된 것인지, 문제의 원인이 어디인지도 맞춰 따라가도록 처리하는 일이에요.', '예를 들어 원본 글자 ABC와 도착 버퍼가 있어도 이 hook만 불러서 도착 글자가 ABC가 된다고 기대하면 안 돼요. 이 함수가 맡는 것은 관련 검사 정보예요. 실제 데이터를 옮기는 단계는 호출 흐름의 다른 곳에서 확인해야 해요.', '앞서 읽은 instrumentation.c의 __msan_memmove는 실제 __memmove를 호출한 뒤 조건에 따라 검사 정보도 옮겨요. 접두사가 다른 두 함수의 본문과 반환형을 비교하세요. 여기의 kmsan_memmove는 void로 끝나고 실제 데이터 이동 호출이 없어요.', '이름의 일부가 같다고 책임이 같지는 않아요. 어떤 단계가 데이터를 옮기고 어떤 단계가 검사표를 갱신하는지 연결해서 읽으면 중복 복사를 넣거나 데이터 복사를 빠뜨리는 오해를 줄일 수 있어요.'], [('kmsan_memmove 본문이 실제 데이터를 복사하는 __memmove나 memcpy를 직접 부르나요?', ['네. 데이터까지 반드시 이 함수에서 옮겨요', '아니요. 내부 검사 정보 이동 helper를 불러요'], '정답은 두 번째예요. 본문의 핵심 호출은 kmsan_internal_memmove_metadata예요. 실제 이동도 부르는 __msan_memmove와 구별하세요.'), ('정상 경로에서 내부 helper를 실행할 때 runtime 상태는 어떠한가요?', ['enter_runtime을 거친 진입 상태예요', '아직 enter_runtime을 실행하기 전이에요'], '정답은 첫 번째예요. 세 호출은 진입, helper, 종료 순서예요. 앞의 조기 반환 조건을 통과한 경로를 기준으로 읽으세요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_449.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
